using BC.FixedAsset.Services;using System;using System.Web.UI.WebControls;
namespace BC.FixedAsset.Web.FixedAsset{public partial class AssetTag:SecurePage{protected Literal litNo,litName,litLocation,litCustodian;protected HiddenField hidQr;protected void Page_Load(object s,EventArgs e){if(IsPostBack)return;long id;var service=new AssetSurveyService();var registered=long.TryParse(Request.QueryString["assetId"],out id);if(!registered&&!long.TryParse(Request.QueryString["id"],out id))throw new InvalidOperationException("Invalid asset.");var t=registered?service.GetRegisterDetail(id):service.Detail(id,AssetAccess);if(t.Rows.Count==0)throw new InvalidOperationException("Asset not found.");var r=t.Rows[0];var number=registered?Convert.ToString(r["FixedAssetNo"]):string.IsNullOrWhiteSpace(Convert.ToString(r["FixedAssetNo"]))?Convert.ToString(r["SurveyNo"]):Convert.ToString(r["FixedAssetNo"]);litNo.Text=H(number);litName.Text=H(r["AssetName"]);litLocation.Text=H(r["BuildingName"]+" / "+r["FloorName"]+" / "+r["RoomName"]);litCustodian.Text=H(r["Custodian"]);hidQr.Value=number;}private string H(object v)=>Server.HtmlEncode(Convert.ToString(v));}}
